import sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Precompute all possible triples a+b=c using distinct elements
triples = []
L_list = list(L)
for i in range(len(L_list)):
    for j in range(i+1, len(L_list)):
        a = L_list[i]
        b = L_list[j]
        c = a + b
        if c in L and c not in (a, b):
            triples.append((a, b, c))
        # also check b + a (same) so no need duplicate

# Backtracking exact cover
solution = []
used = set()

def backtrack(start):
    if len(used) == len(L):
        return True
    # pick smallest unused element to branch
    remaining = [x for x in L if x not in used]
    if not remaining:
        return True
    pivot = min(remaining)
    # try triples that contain pivot
    for a, b, c in triples:
        if pivot not in (a, b, c):
            continue
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack(start+1):
            return True
        # backtrack
        used.difference_update([a, b, c])
        solution.pop()
    return False

found = backtrack(0)
if found:
    witness = {
        "polarity": "positive",
        "evidence": {"path": "execution://witness"},
        "data": {"triples": solution}
    }
else:
